mapper.select:
SELECT b.budget_type, b.expense_category_id, ec.name AS category_name, ucl.custom_name, b.target_amount, COALESCE(e.spent_amount, 0) AS spent_amount, COALESCE(e.expense_count, 0) AS expense_count FROM budgets b JOIN expense_categories ec ON ec.id = b.expense_category_id LEFT JOIN user_category_labels ucl ON ucl.expense_category_id = ec.id AND ucl.user_id = #{userId} LEFT JOIN ( SELECT budget_type, expense_category_id, SUM(amount) AS spent_amount, COUNT(*) AS expense_count FROM workation_expenses WHERE workation_id = #{workationId} GROUP BY budget_type, expense_category_id ) e ON e.budget_type = b.budget_type AND e.expense_category_id = b.expense_category_id WHERE b.workation_id = #{workationId}
AND b.budget_type = #{budgetType}
ORDER BY b.budget_type, ec.sort_order

SELECT COALESCE(SUM(
           CASE WHEN is_auto_categorized = 1 THEN 1 ELSE 0 END
       ), 0) AS unchecked_count
  FROM workation_expenses
 WHERE workation_id = #{workationId}

    AND budget_type = #{budgetType}

SELECT we.id, we.workation_id, we.transaction_id, we.expense_category_id, we.card_id, we.budget_type, we.amount, we.merchant_name, we.spent_at AS spent_date, we.memo, we.is_auto_categorized, we.created_at, we.updated_at, ec.name AS category_name, ucl.custom_name, c.card_name, c.card_number, c.card_type, t.merchant_id, t.approved_number, t.approved_at, t.payment_source_type, m.phone_number AS merchant_phone_number FROM workation_expenses we JOIN expense_categories ec ON ec.id = we.expense_category_id LEFT JOIN user_category_labels ucl ON ucl.expense_category_id = ec.id AND ucl.user_id = #{userId} LEFT JOIN cards c ON c.id = we.card_id LEFT JOIN transactions t ON t.id = we.transaction_id
LEFT JOIN merchants m ON m.id = t.merchant_id WHERE we.workation_id = #{workationId}
AND we.budget_type = #{budgetType}
ORDER BY we.budget_type, we.spent_at, we.id

SELECT budget_type,
       COUNT(DISTINCT DATE(spent_at)) AS spent_day_count
  FROM workation_expenses
 WHERE workation_id = #{workationId}

    AND budget_type = #{budgetType}

 GROUP BY budget_type

SELECT COUNT(*)
  FROM workation_expenses
 WHERE workation_id = #{workationId}

    AND budget_type = #{budgetType}

SELECT DISTINCT CONCAT(c.card_name, ' ', CONCAT(LEFT(c.card_number, 4), '-****-****-', RIGHT(c.card_number, 4))) FROM workation_expenses we LEFT JOIN transactions t ON t.id = we.transaction_id JOIN cards c ON c.id = COALESCE(we.card_id, t.card_id) WHERE we.workation_id = #{workationId} AND c.card_number IS NOT NULL
AND we.budget_type = #{budgetType}
ORDER BY 1
